package com.theminespirit.core.mining;

final class Observe6MineWorld {
    private static final int X0 = -200;
    private static final int Y0 = 61;
    private static final int Z0 = -526;
    private static final int SIZE = 19;
    private static final String[] LAYERS = {
        "#########################################################################################################################################################################################################################################################################################.##################.##############.###.##############.##################.#######",
        "~~#################~##################~#######################################################################################################################################################################.#################..##################.#################...################.##############.###.##############.##################.##########################",
        ".................##.......############.......############.......############.......############.....##############....###############....###############...################...################...############.###...###########...##...############..##...###########....#..#########.###.###..#########.#######..#########.#######..#################..#################",
        "..........................##..########.......############........###########........###########.......############......#############.....##############....###############....###############....###########..##....##########..###....#########....##....#######.#...###...########.#..####...########.##.####....#########..####.....##############......#############",
        "..........................############.......############.......####.....###........#.#########.......############.......############.......############.......############.......############.......########..##.......########..##......#####.###.###......#####.#######.....######.#######.....##############....###############......#############.......############",
        "...........................###########.......############.......############.......########.###.......######.#####.......####.#######............#######.......##..########.......########.###.......########..##.......####.###...#........###.#######.......####.#######.......############.......############....###############.....##############.......############",
        "...........................###########.......############.......###########........##########.........########.###........###..#...##.............#.#..#........##..#.#.###.......##..##.#.###.......##.#.###..##.......####.####...........#.#.#######.......##..########.......############.......############.......############.......############.......############",
        "..........................############.......############.......############.......##########.........########............###................##...##.#..........##.#.##.#..........###.###.#.........####.##............####.##............###................###..##....#.......##...#...#.#.......##...##..#.#.......###..#...#.#.......###..##..#.#.......##...#...#.#",
        "..............................................##.########........#..................#..................#..................#..................#.....#.#..........#.#.#.#.#..........#.#.#..............#.#.#..............#..................#..................#..................#..................#..................#..................#..................#..........",
        "...................................................................................................................................................#.#............#.#................#.#.................................................................................................................................................................................",
        "..................................................................................................................................................................#.#....................................................................................................................................................................................................",
        ".........................................................................................................................................................................................................................................................................................................................................................................",
        ".........................................................................................................................................................................................................................................................................................................................................................................",
        ".........................................................................................................................................................................................................................................................................................................................................................................",
        ".........................................................................................................................................................................................................................................................................................................................................................................",
        ".........................................................................................................................................................................................................................................................................................................................................................................",
        ".........................................................................................................................................................................................................................................................................................................................................................................",
    };

    private Observe6MineWorld() {}

    static CellWorld build() {
        CellWorld world = new CellWorld();
        for (int y = 0; y < LAYERS.length; y++) {
            String layer = LAYERS[y];
            for (int z = 0; z < SIZE; z++) {
                for (int x = 0; x < SIZE; x++) {
                    char cell = layer.charAt(z * SIZE + x);
                    if (cell == '#') {
                        world.set(X0 + x, Y0 + y, Z0 + z, Cell.SOLID);
                    } else if (cell == '~') {
                        world.set(X0 + x, Y0 + y, Z0 + z, Cell.WATER);
                    } else if (cell == 'L') {
                        world.set(X0 + x, Y0 + y, Z0 + z, Cell.LAVA);
                    }
                }
            }
        }
        return world;
    }
}
